<script setup>
import { ref, reactive, onMounted } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { useQuasar } from 'quasar'
import { useCatalogs } from '../stores/catalogs'
import { useAuth } from '../stores/auth'
import { api, unwrap, errorMessage, fieldErrors } from '../services/api'
import { types, canEdit, validateFile } from '../domain'
import PageHeading from '../components/PageHeading.vue'
import AsyncState from '../components/AsyncState.vue'
const route=useRoute(), router=useRouter(), $q=useQuasar(), catalog=useCatalogs(), auth=useAuth()
const id=ref(route.params.id||null), step=ref(1), loading=ref(true), busy=ref(false), error=ref(''), errors=ref({}), files=ref([]), file=ref(null), consent=ref(false), record=ref(null), saved=ref(false)
const maxMB=Number(import.meta.env.VITE_MAX_UPLOAD_MB)||20
const form=reactive({title:'',description:'',type:'documento',resource_date:'',language:'es',license_id:null,category_id:null,collection_id:null,author_ids:[],keyword_ids:[],provenance:'',external_url:'',technical_description:'',technologies:''})
const required=v=>(Array.isArray(v)?v.length>0:!!v)||'Este campo es obligatorio'
async function load(){loading.value=true;error.value='';try{await catalog.load();if(id.value){const r=unwrap((await api.get(`/resources/${id.value}`)).data);if(!canEdit(auth.user,r)){router.replace('/acceso-denegado');return}record.value=r;for(const k of Object.keys(form)){if(k in r)form[k]=r[k]??''}form.license_id=r.license?.id;form.category_id=r.category?.id;form.collection_id=r.collection?.id??null;form.author_ids=r.authors.map(a=>a.id);form.keyword_ids=r.keywords.map(k=>k.id);files.value=r.files||[];saved.value=true}}catch(e){error.value=errorMessage(e)}finally{loading.value=false}}
async function save(){busy.value=true;error.value='';errors.value={};try{const payload={...form,resource_date:form.resource_date||null,collection_id:form.collection_id||null};const response=id.value?await api.put(`/resources/${id.value}`,payload):await api.post('/resources',payload);record.value=unwrap(response.data);id.value=record.value.id;saved.value=true;step.value=2;$q.notify({type:'positive',message:'Metadatos guardados como borrador.'})}catch(e){error.value=errorMessage(e);errors.value=fieldErrors(e)}finally{busy.value=false}}
async function upload(){const invalid=validateFile(file.value,maxMB);if(invalid){$q.notify({type:'negative',message:invalid});return}busy.value=true;try{const body=new FormData();body.append('file',file.value);await api.post(`/resources/${id.value}/files`,body);files.value=unwrap((await api.get(`/resources/${id.value}`)).data).files;file.value=null;$q.notify({type:'positive',message:'Archivo adjuntado.'})}catch(e){$q.notify({type:'negative',message:errorMessage(e)})}finally{busy.value=false}}
function removeFile(item){$q.dialog({title:'Eliminar archivo',message:`¿Desea eliminar ${item.original_name||'este archivo'} del depósito?`,cancel:true,ok:{label:'Eliminar',color:'negative'}}).onOk(async()=>{busy.value=true;try{await api.delete(`/resources/${id.value}/files/${item.id}`);files.value=files.value.filter(f=>f.id!==item.id)}catch(e){$q.notify({type:'negative',message:errorMessage(e)})}finally{busy.value=false}})}
async function submit(){if(!consent.value)return;busy.value=true;try{await api.post(`/resources/${id.value}/submit`);$q.notify({type:'positive',message:'Depósito enviado a revisión.'});router.replace(`/recursos/${id.value}`)}catch(e){error.value=errorMessage(e)}finally{busy.value=false}}
onMounted(load)
</script>
<template><PageHeading :title="route.params.id?'Editar depósito':'Nuevo depósito'" subtitle="Complete los metadatos, adjunte archivos y confirme el envío a revisión." /><AsyncState :loading="loading" :error="!saved&&error&&!Object.keys(errors).length?error:''" @retry="load"><p v-if="error" class="alert" role="alert">{{ error }}</p><q-stepper v-model="step" color="primary" animated flat><q-step :name="1" title="Metadatos" icon="description" :done="step>1"><q-form @submit="save"><div class="form-grid"><q-select v-model="form.collection_id" :options="catalog.collections" option-label="name" option-value="id" emit-value map-options clearable outlined label="Colección" /><q-select v-model="form.type" :options="types" emit-value map-options outlined label="Tipo de recurso *" /><q-input v-model="form.title" outlined label="Título *" maxlength="255" :rules="[required]" :error="!!errors.title" :error-message="errors.title" class="full-width-field" /><q-input v-model="form.description" outlined type="textarea" label="Resumen o descripción *" :rules="[required]" :error="!!errors.description" :error-message="errors.description" class="full-width-field" /><q-select v-model="form.author_ids" :options="catalog.authors" option-label="name" option-value="id" emit-value map-options multiple use-chips outlined label="Autoría *" :rules="[required]" :error="!!errors.author_ids" :error-message="errors.author_ids" /><q-select v-model="form.category_id" :options="catalog.categories" option-label="name" option-value="id" emit-value map-options outlined label="Categoría *" :rules="[required]" :error="!!errors.category_id" :error-message="errors.category_id" /><q-input v-model="form.resource_date" type="date" outlined stack-label label="Fecha del recurso" :error="!!errors.resource_date" :error-message="errors.resource_date" /><q-input v-model="form.language" outlined label="Idioma" maxlength="10" hint="Código de idioma, por ejemplo: es o en" /><q-select v-model="form.keyword_ids" :options="catalog.keywords" option-label="name" option-value="id" emit-value map-options multiple use-chips outlined label="Palabras clave" /><q-select v-model="form.license_id" :options="catalog.licenses" option-label="name" option-value="id" emit-value map-options outlined label="Licencia *" :rules="[required]" :error="!!errors.license_id" :error-message="errors.license_id" /><q-input v-model="form.provenance" outlined label="Procedencia" maxlength="500" class="full-width-field" /><q-input v-model="form.external_url" outlined label="Enlace externo o repositorio" type="url" maxlength="500" :error="!!errors.external_url" :error-message="errors.external_url" class="full-width-field" /><template v-if="form.type==='proyecto'"><q-input v-model="form.technical_description" outlined type="textarea" label="Descripción técnica *" :rules="[required]" :error="!!errors.technical_description" :error-message="errors.technical_description" class="full-width-field" /><q-input v-model="form.technologies" outlined label="Tecnologías utilizadas" maxlength="500" class="full-width-field" /></template></div><div class="actions"><q-btn color="primary" unelevated label="Guardar y continuar" type="submit" :loading="busy" /><q-btn flat to="/depositos" label="Volver a mis depósitos" :disable="busy" /></div></q-form></q-step>
<q-step :name="2" title="Archivos y derechos" icon="attach_file" :done="step>2"><h2>Archivos del recurso</h2><p class="muted">PDF, DOC, DOCX, ODT, PPT, PPTX, ZIP o TXT. Máximo {{ maxMB }} MB por archivo; el servidor aplica la validación definitiva.</p><div v-for="item in files" :key="item.id" class="file-row"><span>{{ item.original_name||item.name||`Archivo ${item.id}` }}</span><q-btn flat color="negative" icon="delete_outline" aria-label="Eliminar archivo" :disable="busy" @click="removeFile(item)" /></div><div class="search-row q-mt-lg"><q-file v-model="file" outlined label="Seleccionar archivo" accept=".pdf,.doc,.docx,.odt,.ppt,.pptx,.zip,.txt" :disable="busy"><template #prepend><q-icon name="upload_file" /></template></q-file><q-btn color="primary" label="Adjuntar archivo" :loading="busy" :disable="!file" @click="upload" /></div><p class="notice">La licencia seleccionada es {{ catalog.licenses.find(l=>l.id===form.license_id)?.name }}. Adjunte únicamente archivos que esté autorizado a distribuir.</p><div class="actions"><q-btn flat label="Volver a metadatos" :disable="busy" @click="step=1" /><q-btn color="primary" label="Continuar" :disable="busy" @click="step=3" /><q-btn flat label="Guardar y salir" :to="`/recursos/${id}`" :disable="busy" /></div></q-step>
<q-step :name="3" title="Confirmación" icon="fact_check"><h2>Revisar antes de enviar</h2><dl class="metadata"><dt>Título</dt><dd>{{ form.title }}</dd><dt>Tipo</dt><dd>{{ form.type }}</dd><dt>Autoría</dt><dd>{{ catalog.authors.filter(a=>form.author_ids.includes(a.id)).map(a=>a.name).join(', ') }}</dd><dt>Archivos</dt><dd>{{ files.length }} adjuntos</dd><dt>Licencia</dt><dd>{{ catalog.licenses.find(l=>l.id===form.license_id)?.name }}</dd></dl><q-checkbox v-model="consent" label="Confirmo la autoría, la procedencia y la autorización para enviar este material a revisión." class="q-mt-lg" /><p class="muted q-mt-md">El envío no publica el recurso. El revisor verificará el contenido antes de su aprobación.</p><div class="actions"><q-btn flat label="Volver a archivos" :disable="busy" @click="step=2" /><q-btn color="primary" label="Confirmar envío a revisión" :disable="!consent" :loading="busy" @click="submit" /><q-btn flat label="Conservar borrador" :to="`/recursos/${id}`" :disable="busy" /></div></q-step></q-stepper></AsyncState></template>
